  "check_code": "from pathlib import Path
import sqlite3


DB_REL = Path("system/sharepoint_hr_governance/state.db")
COLS = (
    "decision_id", "assessment_id", "recommendation_code", "recommendation_text",
    "decision_owner_id", "decision_owner", "executive_recipient_id",
    "executive_recipient", "decision_status", "decision_date", "due_date",
    "follow_up_date_id", "funding_program_id", "recommended_amount_cents",
    "implementation_status",
)
BASELINE = [('DEC-IE-24-404', 'PEA-IE-2024Q4-007-D2', 'REC-VARPAY-REVIEW', 'Review variable-pay eligibility rules for employees transferring between legal entities.', 'HR-OWNER-EM', 'Eleanor Murphy', 'NORTHSTAR-IE-PCL', 'Ireland People and Culture Leadership', 'In Progress', '2025-02-14', '2025-04-11', 'DATE-2025-04-18', None, None, 'Payroll and HR policy review underway'), ('DEC-IE-24-411', 'PEA-IE-2024Q4-007-D2', 'REC-MODEL-DOC', 'Publish the approved factor dictionary with model ownership and change-control requirements.', 'HR-OWNER-DW', 'Declan Walsh', 'NORTHSTAR-IE-PCL', 'Ireland People and Culture Leadership', 'Approved', '2025-02-14', '2025-03-07', 'DATE-2025-04-18', None, None, 'Controlled methodology issued'), ('DEC-IE-26-609', 'PEA-IE-2025Q4-012-D1', 'REC-DATA-QUALITY', 'Remediate employing-entity and work-location conflicts before final population certification.', 'HR-OWNER-SK', 'Saoirse Kelly', 'REDWOOD-IE-PB', 'Ireland People Board', 'Scheduled', '2026-02-18', '2026-03-20', 'DATE-2026-05-22', None, None, 'Data-owner working session scheduled'), ('DEC-UK-25-081', 'PEA-UK-2025Q3-014-A3', 'REC-FUND-2025', 'Approve FY2025 remediation funding including employer on-cost.', 'HR-OWNER-AG', 'Amelia Grant', 'MSFT-UK-PLT', 'Microsoft UK Ltd People Leadership Team', 'Approved', '2025-11-06', '2025-11-21', 'DATE-2026-01-31', 'SN-FUND-2025-UK-8841', 138302627, 'Funding program released'), ('DEC-UK-25-083', 'PEA-UK-2025Q3-014-A3', 'REC-ADJUST-2025', 'Implement approved adjustment actions for validated recommended cases.', 'HR-OWNER-AG', 'A. Grant', 'MSFT-UK-PLT', 'Microsoft UK People Leadership Team', 'In Progress', '2025-11-06', '2025-12-19', 'DATE-2026-01-31', 'SN-FUND-2025-UK-8841', 120999674, 'Actions queued in ServiceNow'), ('DEC-UK-25-086', 'PEA-UK-2025Q3-014-A3', 'REC-VALIDATE-2025', 'Complete data and manager validation for held outlier cases before adjustment.', 'HR-OWNER-AG', 'Amelia Grant - Compensation', 'MSFT-UK-PLT', 'UK People Leadership Team', 'Pending Validation', '2025-11-06', '2026-01-16', 'DATE-2026-01-31', None, None, 'Twelve cases held for validation'), ('DEC-UK-25-089', 'PEA-UK-2025Q3-014-A3', 'REC-MONITOR-2025', 'Review remediation completion and held-case outcomes with People Leadership.', 'HR-OWNER-AG', 'Amelia Grant', 'MSFT-UK-PLT', 'Microsoft UK Ltd People Leadership Team', 'Scheduled', '2025-11-06', '2026-01-31', 'DATE-2026-01-31', None, None, 'Agenda reserved'), ('DEC-UK-25-092', 'PEA-UK-2025Q3-014-A3', 'REC-MODEL-REFRESH-2026', 'Refresh the approved model after the follow-up review using the next compensation snapshot.', 'HR-OWNER-AG', 'A. Grant', 'MSFT-UK-PLT', 'Microsoft UK People Leadership Team', 'Scheduled', '2025-11-06', '2026-02-20', 'DATE-2026-01-31', None, None, 'Dependent on January review'), ('DEC-UK-25-507', 'PEA-UK-2025Q1-022-D1', 'REC-CALIBRATION-EXCEPTIONS', 'Escalate awards outside the documented market range for committee review.', 'HR-OWNER-RB', 'Rachel Bennett', 'HF-UK-REMCO', 'UK Remuneration Committee', 'Pending Validation', '2025-05-08', '2025-05-30', 'DATE-2025-07-25', None, None, 'Supporting market data requested'), ('DEC-UK-25-521', 'PEA-UK-2025Q1-022-D1', 'REC-EXTRACT-CORRECTION', 'Correct the quarter-end compensation extract before legal review resumes.', 'HR-OWNER-DP', 'Daniel Price', 'HF-UK-REMCO', 'UK Remuneration Committee', 'Scheduled', '2025-05-08', '2025-05-16', 'DATE-2025-07-25', None, None, 'Workday correction window booked'), ('DEC-UK-25-546', 'PEA-UK-2025Q2-031-S3', 'REC-BENEFIT-ENROLLMENT', 'Resolve pension enrollment exceptions identified in the June benefits audit.', 'HR-OWNER-OH', 'Oliver Hughes', 'WESTBRIDGE-UK-ELT', 'UK Executive Leadership Team', 'In Progress', '2025-07-24', '2025-09-12', 'DATE-2025-11-14', 'HRSD-WBH-BEN-2507', 1874350, 'Eleven of fourteen records corrected'), ('DEC-UK-25-568', 'PEA-UK-2025Q2-031-S3', 'REC-CLINICAL-PREMIUM', 'Revise the model treatment of clinical shift premiums before management reliance.', 'HR-OWNER-CL', 'Catherine Lewis', 'WESTBRIDGE-UK-ELT', 'UK Executive Leadership Team', 'Approved', '2025-07-24', '2025-08-22', 'DATE-2025-11-14', None, None, 'Replacement model commissioned')]


def _db(ws):
    return sqlite3.connect(ws.parent / DB_REL)


def check_new_validation_decision(ws):
    with _db(ws) as conn:
        rows = conn.execute(
            "SELECT " + ", ".join(COLS) + " FROM recommendation_decisions "
            "WHERE assessment_id=? AND recommendation_code=? AND decision_status=? "
            "AND decision_date=? AND due_date=? AND decision_owner_id=? "
            "AND executive_recipient_id=? AND follow_up_date_id=?",
            ("PEA-UK-2025Q3-014-A3", "REC-VALIDATE-2025", "Pending Validation",
             "2026-08-14", "2026-09-30", "HR-OWNER-AG", "MSFT-UK-PLT", "DATE-2026-01-31"),
        ).fetchall()
    if len(rows) != 1:
        return {"score": 0, "detail": f"Expected exactly one new matching decision, found {len(rows)}."}
    row = dict(zip(COLS, rows[0]))
    expected = {
        "recommendation_text": "Complete data and manager validation for held outlier cases before adjustment.",
        "decision_owner": "Amelia Grant",
        "executive_recipient": "Microsoft UK Ltd People Leadership Team",
        "funding_program_id": None,
        "recommended_amount_cents": None,
        "implementation_status": "Twelve cases remain pending data and manager validation.",
    }
    wrong = {}
    for key, value in expected.items():
        actual = row[key]
        if key == 'implementation_status':
            actual_cmp = str(actual).strip().rstrip('.').strip()
            expected_cmp = str(value).strip().rstrip('.').strip()
        else:
            actual_cmp = actual
            expected_cmp = value
        if actual_cmp != expected_cmp:
            wrong[key] = (actual, value)
    if wrong:
        return {"score": 0, "detail": f"New decision has incorrect fields: {wrong}"}
    if row["decision_id"] in {item[0] for item in BASELINE}:
        return {"score": 0, "detail": "The matching row reused a pre-existing decision identifier."}
    with _db(ws) as conn:
        total = conn.execute("SELECT COUNT(*) FROM recommendation_decisions").fetchone()[0]
    if total != len(BASELINE) + 1:
        return {"score": 0, "detail": f"Expected one new decision and {len(BASELINE) + 1} total rows, found {total}."}
    return {"score": 1, "detail": f"Persisted new decision {row['decision_id']} with the approved IDs, due date, hold wording, and no funding reference."}


def check_prior_decisions_unchanged(ws):
    with _db(ws) as conn:
        rows = conn.execute("SELECT " + ", ".join(COLS) + " FROM recommendation_decisions ORDER BY decision_id").fetchall()
    actual = [tuple(row) for row in rows if row[0] in {item[0] for item in BASELINE}]
    expected = sorted(BASELINE, key=lambda item: item[0])
    if sorted(actual, key=lambda item: item[0]) != expected:
        return {"score": 0, "detail": "One or more pre-existing recommendation decisions changed or was deleted."}
    return {"score": 1, "detail": "All pre-existing recommendation decisions remain unchanged."}
